package com.campx.academic.attendance.security;

import com.campx.academic.attendance.exception.AttendanceUnauthorizedException;
import com.campx.logger.CampXLogger;
import com.campx.logger.CampXLoggerFactory;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;

/**
 * Validates HMAC-SHA256 signatures generated by the CampXSync API Gateway
 * to prevent header spoofing and replay attacks for Attendance Management Service.
 */
public class GatewayHmacVerifier {

    private static final CampXLogger logger = CampXLoggerFactory.getLogger(GatewayHmacVerifier.class);
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final long MAX_SKEW_SECONDS = 300; // 5 minutes window

    private final String secret;

    public GatewayHmacVerifier(String secret) {
        this.secret = secret;
    }

    public void verify(String method, String path, String timestamp, String signature, String body) {
        if (secret == null || secret.trim().isEmpty()) {
            logger.warn("Gateway HMAC secret not configured; skipping HMAC check in isolated testing");
            return;
        }

        if (timestamp == null || signature == null) {
            throw new AttendanceUnauthorizedException("Missing required gateway signature headers");
        }

        long epoch;
        try {
            epoch = Long.parseLong(timestamp.trim());
        } catch (NumberFormatException e) {
            throw new AttendanceUnauthorizedException("Invalid gateway timestamp format");
        }

        long now = Instant.now().getEpochSecond();
        if (Math.abs(now - epoch) > MAX_SKEW_SECONDS) {
            throw new AttendanceUnauthorizedException("Gateway signature expired or clock skew exceeded");
        }

        String canonical = method.toUpperCase() + "\n" + path + "\n" + timestamp + "\n" + (body != null ? body : "");
        String calculated = calculateHmac(canonical, secret);

        if (!MessageDigest.isEqual(calculated.getBytes(StandardCharsets.UTF_8), signature.trim().getBytes(StandardCharsets.UTF_8))) {
            throw new AttendanceUnauthorizedException("Gateway HMAC signature verification failed");
        }
    }

    public static String calculateHmac(String data, String key) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            mac.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM));
            byte[] rawHmac = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(rawHmac.length * 2);
            for (byte b : rawHmac) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Failed to calculate HMAC signature", e);
        }
    }
}
